//! 🪪️ Exact original 64-frame identity backing is initialized one funded prefix slot at a time.
use super::*;
use super::super::{JsonFrame,ScalarBytes,ARTIFACT_CANONICAL_JSON_DEPTH};
use std::mem::MaybeUninit;
const CONTROL:usize=2*size_of::<usize>()+size_of::<u8>();
/// 🎟️ One staged birth turn keeps the original physical frame and transfers only its fully initialized owner.
#[derive(Default)]
pub struct ArtifactCanonicalSourceIdentityBirth{allocation:Option<Box<MaybeUninit<ArtifactCanonicalSourceIdentityCursor>>>,ready:Option<Box<ArtifactCanonicalSourceIdentityCursor>>,roots:usize,index:usize,phase:u8}
impl ArtifactCanonicalSourceIdentityBirth{
 pub fn original_backing_identity(&self)->Option<usize>{self.allocation.as_ref().map(|frame|frame.as_ptr()as usize).or_else(||self.ready.as_ref().map(|frame|&**frame as*const ArtifactCanonicalSourceIdentityCursor as usize))}
 pub fn initialized_slots(&self)->usize{self.index}
 pub fn terminal_is_empty(&self)->bool{matches!(self.phase,6|8)&&self.allocation.is_none()&&self.ready.is_none()}
 pub fn next_demand(&self)->RetirementDemand{let copy=match self.phase{0=>2*size_of::<Option<Box<MaybeUninit<ArtifactCanonicalSourceIdentityCursor>>>>()+CONTROL,1=>2*(size_of::<JsonFrame>()+size_of::<usize>())+CONTROL,2=>2*(3*size_of::<usize>()+size_of::<ScalarBytes>()+size_of::<[u8;6]>()+2*size_of::<usize>())+CONTROL,3=>2*(size_of::<Sha256>()+size_of::<Option<[u8;32]>>()+size_of::<Option<usize>>()+3*size_of::<usize>()+size_of::<u8>())+CONTROL,4|5=>2*(size_of::<Option<Box<ArtifactCanonicalSourceIdentityCursor>>>()+size_of::<Option<Box<MaybeUninit<ArtifactCanonicalSourceIdentityCursor>>>>())+CONTROL,_=>0};RetirementDemand{copy_bytes:copy,capacity_bytes:usize::from(self.phase==0)*size_of::<ArtifactCanonicalSourceIdentityCursor>(),depth:usize::from(copy!=0),..Default::default()}}
 pub fn advance(&mut self,roots:usize,grant:RetainedCloneGrant)->Result<(Option<Box<ArtifactCanonicalSourceIdentityCursor>>,RetainedCloneProgress),ValueError>{if roots>64{return Err(ValueError::literal(ValueRefusalKind::WorkLimit,"canonical identity birth exceeds64 original roots"));}if self.phase>0&&self.roots!=roots{return Err(invalid("canonical identity birth root policy changed"));}if self.phase>=6{return Ok((None,Default::default()));}let d=self.next_demand();if !fits(d,grant){return Ok((None,Default::default()));}let mut delivered=None;match self.phase{
 0=>{self.roots=roots;self.allocation=Some(Box::<ArtifactCanonicalSourceIdentityCursor>::new_uninit());self.phase=1;},
 1=>{let pointer=self.allocation.as_mut().unwrap().as_mut_ptr();unsafe{std::ptr::addr_of_mut!((*pointer).cursor.frames).cast::<JsonFrame>().add(self.index).write(JsonFrame::default());std::ptr::addr_of_mut!((*pointer).cursor.path).cast::<usize>().add(self.index).write(0);}self.index+=1;if self.index==ARTIFACT_CANONICAL_JSON_DEPTH{self.phase=2;}},
 2=>{let pointer=self.allocation.as_mut().unwrap().as_mut_ptr();unsafe{std::ptr::addr_of_mut!((*pointer).cursor.depth).write(1);std::ptr::addr_of_mut!((*pointer).cursor.maximum_depth).write(ARTIFACT_CANONICAL_JSON_DEPTH);std::ptr::addr_of_mut!((*pointer).cursor.scalar).write(ScalarBytes{bytes:[0;64],length:0});std::ptr::addr_of_mut!((*pointer).cursor.escape).write([0;6]);std::ptr::addr_of_mut!((*pointer).cursor.escape_length).write(0);std::ptr::addr_of_mut!((*pointer).cursor.escape_offset).write(0);}self.phase=3;},
 3=>{let pointer=self.allocation.as_mut().unwrap().as_mut_ptr();unsafe{std::ptr::addr_of_mut!((*pointer).hash).write(Sha256::new());std::ptr::addr_of_mut!((*pointer).digest).write(None);std::ptr::addr_of_mut!((*pointer).root).write(None);std::ptr::addr_of_mut!((*pointer).roots).write(self.roots);std::ptr::addr_of_mut!((*pointer).index).write(0);std::ptr::addr_of_mut!((*pointer).offset).write(0);std::ptr::addr_of_mut!((*pointer).phase).write(0);}self.phase=4;},
 4=>{self.ready=Some(unsafe{self.allocation.take().unwrap().assume_init()});self.phase=5;},
 5=>{delivered=self.ready.take();self.phase=6;},
 _=>unreachable!(),
 }Ok((delivered,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,..Default::default()}))}
 pub fn close_demand(&self)->RetirementDemand{if self.terminal_is_empty(){return Default::default();}if let Some(cursor)=self.ready.as_ref(){if !cursor.terminal_is_empty(){return RetirementDemand{copy_bytes:size_of::<ArtifactCanonicalSourceIdentityCursor>()+CONTROL,depth:2,..Default::default()};}}RetirementDemand{copy_bytes:2*size_of::<Self>(),release_bytes:usize::from(self.allocation.is_some()||self.ready.is_some())*size_of::<ArtifactCanonicalSourceIdentityCursor>(),depth:1,..Default::default()}}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{let d=self.close_demand();if self.terminal_is_empty()||!fits(d,grant){return Ok(Default::default());}if let Some(cursor)=self.ready.as_mut(){if !cursor.terminal_is_empty(){cursor.begin_close();let mut p=cursor.close_step(RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-CONTROL,maximum_depth:grant.maximum_depth-1,..grant})?.progress;p.copied_bytes+=CONTROL;return Ok(p);}}self.allocation=None;self.ready=None;self.index=0;self.roots=0;self.phase=8;Ok(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()})}
}
impl Drop for ArtifactCanonicalSourceIdentityBirth{fn drop(&mut self){assert!(std::thread::panicking()||self.allocation.is_none()&&self.ready.is_none(),"canonical identity staged birth retains its original paid backing until terminal handoff or close");}}